document.querySelectorAll('[data-wa]').forEach(link => {
  link.href = 'https://wa.me/553591558356?text=' + encodeURIComponent(link.dataset.wa);
  link.target = '_blank';
  link.rel = 'noopener noreferrer';
});
// Reveal only below-the-fold sections, once; keep content visible without support.
const motionPreference=matchMedia('(prefers-reduced-motion: reduce)');
if('IntersectionObserver' in window&&!motionPreference.matches){
 const targets=document.querySelectorAll('.section-heading,.iphone-card,.xiaomi-card,.games-card,.about-grid,.store-card');
 const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.remove('reveal-pending');observer.unobserve(entry.target);}});},{threshold:0.08});
 targets.forEach(el=>{if(el.getBoundingClientRect().top>=innerHeight){el.classList.add('reveal-pending');observer.observe(el);}});
 motionPreference.addEventListener('change',()=>{if(motionPreference.matches){targets.forEach(el=>el.classList.remove('reveal-pending'));observer.disconnect();}});
}
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let catalog=[],storeSettings={theme:'light',accent:'orange'};
const section=document.querySelector('#produtos');
const tools=document.createElement('div');tools.className='shop-tools';tools.hidden=true;tools.innerHTML=`
 <div class="shop-search-row"><input id="shop-search" type="search" aria-label="Buscar produtos" placeholder="Encontre seu próximo produto…"><select id="shop-category" aria-label="Categoria"><option value="">Todas as categorias</option><option>iPhone</option><option>Xiaomi</option><option>PlayStation</option><option>Xbox</option><option>Acessórios</option></select></div>
 <details class="shop-filter-panel"><summary>Mais filtros <span aria-hidden="true">+</span></summary><div class="shop-filter-fields"><label>Condição<select id="shop-condition"><option value="">Novos e seminovos</option><option value="Novo">Novo</option><option value="Seminovo">Seminovo</option></select></label><label>Preço mínimo (R$)<input id="shop-min" type="number" min="0" step="0.01" inputmode="decimal" placeholder="0,00"></label><label>Preço máximo (R$)<input id="shop-max" type="number" min="0" step="0.01" inputmode="decimal" placeholder="Sem limite"></label><label class="shop-stock-filter"><input id="shop-stock-only" type="checkbox">Somente em estoque</label></div><p class="shop-price-help" id="shop-price-help" hidden>A faixa considera o preço inicial anunciado. Produtos com preço sob consulta ficam fora do filtro de preço.</p></details>
 <div class="shop-results-row"><p id="shop-results" role="status" aria-live="polite" aria-atomic="true"></p><button id="shop-reset" type="button" hidden>Limpar filtros</button><label class="shop-sort-label">Ordenar por<select id="shop-sort"><option value="featured">Destaques</option><option value="price-asc">Menor preço</option><option value="price-desc">Maior preço</option><option value="name">Nome A–Z</option></select></label></div>`;

const grid=document.createElement('div');grid.className='live-catalog';grid.hidden=true;section.querySelector('.catalog-visit').after(tools,grid);const compareEntry=document.createElement('a');compareEntry.className='compare-entry';compareEntry.href='/comparar';compareEntry.textContent='Comparar dois celulares ↗';tools.before(compareEntry);
function renderCatalog(){
 const q=document.querySelector('#shop-search').value.trim().toLocaleLowerCase('pt-BR'),cat=document.querySelector('#shop-category').value,condition=document.querySelector('#shop-condition').value,stockOnly=document.querySelector('#shop-stock-only').checked,sort=document.querySelector('#shop-sort').value;
 const minInput=document.querySelector('#shop-min'),maxInput=document.querySelector('#shop-max'),hasMin=minInput.value!=='',hasMax=maxInput.value!=='',hasPrice=hasMin||hasMax,min=hasMin?Math.round(Number(minInput.value)*100):0,max=hasMax?Math.round(Number(maxInput.value)*100):Infinity;
 const invalid=!minInput.validity.valid||!maxInput.validity.valid||min>max;
 minInput.setAttribute('aria-invalid',String(invalid));maxInput.setAttribute('aria-invalid',String(invalid));
 document.querySelector('#shop-reset').hidden=!(q||cat||condition||stockOnly||hasPrice||invalid||sort!=='featured');document.querySelector('#shop-price-help').hidden=!hasPrice;
 const list=invalid?[]:catalog.filter(p=>(!cat||p.category===cat)&&(!condition||p.condition===condition)&&(!stockOnly||p.stock>0)&&(!hasPrice||(Number.isFinite(p.price)&&p.price>=min&&p.price<=max))&&p.name.toLocaleLowerCase('pt-BR').includes(q));
 if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));else if(sort.startsWith('price-'))list.sort((a,b)=>{if(!Number.isFinite(a.price))return Number.isFinite(b.price)?1:0;if(!Number.isFinite(b.price))return -1;return sort==='price-asc'?a.price-b.price:b.price-a.price;});
 document.querySelector('#shop-results').textContent=invalid?'Revise os preços: use valores positivos e mínimo menor ou igual ao máximo.':list.length+' '+(list.length===1?'produto encontrado':'produtos encontrados');
grid.innerHTML=list.length?list.map(p=>{const message=p.stock>0?'Olá! Tenho interesse no produto '+p.name+'. Gostaria de saber mais.':'Olá! Gostaria de saber sobre a reposição do produto '+p.name+'.';const href='https://wa.me/553591558356?text='+encodeURIComponent(message);return `<article class="shop-product"><div class="shop-photo"><a href="/produto/${encodeURIComponent(p.id)}" aria-label="Ver detalhes de ${escapeHTML(p.name)}">${p.image?`<img src="${escapeHTML(p.image)}" alt="${escapeHTML(p.name)}" loading="lazy" referrerpolicy="no-referrer">`:'<span aria-hidden="true">▦</span>'}</a>${p.featured?'<span class="shop-featured">DESTAQUE</span>':''}</div><div class="shop-details"><p class="shop-meta">${escapeHTML(p.category)} · ${escapeHTML(p.condition)}</p><h3><a href="/produto/${encodeURIComponent(p.id)}">${escapeHTML(p.name)}</a></h3><p class="shop-price">${p.details?.variants?.length&&p.price!==null?'<span class="shop-price-prefix">A partir de</span>':''}${p.price===null?'Sob consulta':(p.price/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}</p><p class="shop-stock ${p.stock===0?'out':''}">${p.stock>0?'Disponível em estoque':'Sem estoque no momento'}</p><a class="button orange" href="/produto/${encodeURIComponent(p.id)}">Ver detalhes <span aria-hidden="true">↗</span></a><button type="button" class="favorite-button" data-favorite="${escapeHTML(p.id)}" aria-pressed="false">♡ Salvar favorito</button>${['iPhone','Xiaomi'].includes(p.category)?`<button class="compare-button" type="button" data-compare="${escapeHTML(p.id)}" aria-pressed="false">Comparar celular</button>`:''}</div></article>`;}).join(''):'<p class="shop-empty">Nenhum produto encontrado. Ajuste os filtros ou use “Limpar filtros”.</p>';document.dispatchEvent(new Event('up:products-rendered'));grid.querySelectorAll('img').forEach(img=>img.onerror=()=>{const span=document.createElement('span');span.textContent='▦';span.setAttribute('aria-label','Foto indisponível');img.replaceWith(span);});}
tools.addEventListener('input',e=>{if(e.target.matches('input'))renderCatalog();});tools.addEventListener('change',e=>{if(e.target.matches('select'))renderCatalog();});
 document.querySelector('#shop-reset').onclick=()=>{tools.querySelectorAll('input').forEach(input=>{if(input.type==='checkbox')input.checked=false;else input.value='';});document.querySelector('#shop-category').value='';document.querySelector('#shop-condition').value='';document.querySelector('#shop-sort').value='featured';renderCatalog();};
const footerControls=document.createElement('div');footerControls.className='footer-admin';footerControls.innerHTML='<a href="/conta" data-account-link>Entrar</a><a href="/admin" class="store-admin" data-admin-link hidden>Área administrativa ↗</a><select class="theme-select" id="visitor-theme" aria-label="Tema da sua visualização"><option value="default">Tema da loja</option><option value="light">Claro</option><option value="dark">Escuro</option><option value="system">Automático</option></select>';document.querySelector('footer').append(footerControls);
try{document.querySelector('#visitor-theme').value=localStorage.getItem('up-visitor-theme')||'default';}catch{}
function updateVisitorTheme(){const mode=document.querySelector('#visitor-theme').value;applyTheme({...storeSettings,theme:mode==='default'?storeSettings.theme:mode});}
document.querySelector('#visitor-theme').onchange=()=>{try{localStorage.setItem('up-visitor-theme',document.querySelector('#visitor-theme').value);}catch{}updateVisitorTheme();};matchMedia('(prefers-color-scheme: dark)').addEventListener('change',updateVisitorTheme);
fetch('/api/catalog').then(async r=>{if(!r.ok)throw new Error();return r.json();}).then(data=>{catalog=data.products;storeSettings=data.settings;updateVisitorTheme();if(catalog.length){section.querySelector('.product-grid').hidden=true;grid.hidden=false;tools.hidden=false;renderCatalog();document.querySelector('.category-strip a[href="#iphones"]').href='#produtos';}}).catch(()=>{const p=document.createElement('p');p.className='catalog-error';p.textContent='O catálogo está temporariamente indisponível. Consulte os produtos pelo WhatsApp.';section.append(p);updateVisitorTheme();});
